//! Can a *catopt* language be assembled from data?
//!
//! Spike Q0 of `plan 0029` (catopt `project/plans/0029-handl-catopt-boundary-spike.md`):
//! catopt's bridge emits handl-shaped rows (`AstShapeDef`, `TransformDef`);
//! this test asserts that the **ten-file data layout** `language_from_dir`
//! reads can carry them — i.e. that catopt's vocabulary is expressible as
//! handl data, not merely *similar* to it.
//!
//! The fixture directory `tests/data/catopt-fragments/` is **generated by
//! catopt** (`lab/handl-spike/dump_fragments.py`, committed there) and
//! copied here verbatim: eight shell files (empty — catopt's "syntax" is
//! the IR, not a text language) plus `transforms.yaml`, carrying one
//! structural law (`assoc_add`) as a `TransformDef`.
//!
//! What this does and does not prove:
//!
//! * proves — the merge path accepts catopt's rows, the law lands in
//!   `lang.transforms` with its fields intact, and the folded `when`
//!   condition deserializes as `And([KindAt, ChildCount])`.
//! * does not prove — that a rewrite *fires* on a catopt term (that needs
//!   an AST, i.e. the next step of the spike), nor anything about tensor
//!   values (spike Q1).

use std::path::Path;

use handl_kit_data_canonical::language_from_dir;
use handl_language::TransformCondition;

fn fixture_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/catopt-fragments")
}

#[test]
fn catopt_fragment_dir_assembles_a_language() {
    let lang = language_from_dir(&fixture_dir())
        .expect("catopt's fragment directory must merge into a Language");

    let ids: Vec<&str> = lang.transforms.iter().map(|d| d.id.as_str()).collect();
    assert!(
        ids.iter().any(|i| *i == "transform.catopt.assoc_add"),
        "expected catopt's law among {ids:?}"
    );
}

#[test]
fn catopt_law_survives_as_data() {
    let lang = language_from_dir(&fixture_dir()).expect("merges");
    let def = lang
        .transforms
        .get_by_id("transform.catopt.assoc_add")
        .expect("the law is retrievable by id");

    assert_eq!(def.pass, "catopt");
    assert_eq!(def.node_kind, "add");

    // `when` is ONE TransformCondition; catopt's clause list must have
    // folded into `And([...])` to deserialize at all.
    match def.when.as_ref().expect("when is present") {
        TransformCondition::And(parts) => assert_eq!(parts.len(), 2, "KindAt + ChildCount"),
        other => panic!("expected And([...]), got {other:?}"),
    }
}

// --- the full bank ---------------------------------------------------------

fn full_bank_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/catopt-fragments-all")
}

/// The whole shipped bank (every rule), not the one-law slice.
///
/// **This test pins a known gap.**  The slice above loads because
/// `assoc_add` is purely structural; the full bank does not, because
/// some law's right-hand side contains a *leaf* — catopt spells it
/// `{"catopt:leaf": …}`, and handl's `RewriteStep` vocabulary has no
/// counterpart for a literal (or a variable) child.  The bridge emits a
/// map there, which is not a YAML tag, so the load fails.
///
/// So the honest statement of Q0's result is: catopt's vocabulary is
/// expressible as handl data **for structural laws**; leaf-bearing laws
/// need a mapping first — candidates are `Create` with the value in the
/// node's `payload` (for constants) and `Fresh(hint)` (for variables).
///
/// When that mapping lands, this test flips: assert `Ok` and the full
/// transform count instead of the failure.
#[test]
fn catopt_full_bank_leaf_gap_is_pinned() {
    match language_from_dir(&full_bank_dir()) {
        Ok(lang) => panic!(
            "the full bank now loads ({} transforms) — the leaf gap is closed; \
             flip this test to assert success",
            lang.transforms.iter().count()
        ),
        Err(e) => {
            let msg = format!("{e}");
            assert!(
                msg.contains("expected a YAML tag"),
                "expected the leaf gap, got: {msg}"
            );
            println!("full bank load fails as recorded: {msg}");
        }
    }
}
